function render({width,state,params}) {
  const w = Number.isFinite(width) ? Math.max(320, Math.min(760, width)) : 640;
  const key = typeof state === 'string' ? state : state && state.key;
  const mode = key === 'row' ? 'row' : 'batch';
  const X = [[[0,1,2,3],[3,1,0,2]],[[1,0,3,2],[2,3,1,0]]];
  const lengths = mode === 'row' ? [[1,3],[2,4]] : [2,3];
  const expanded = mode === 'row' ? [1,3,2,4] : [2,2,3,3];
  const rows = X[0].concat(X[1]);
  const masked = rows.map((r,i) => r.map((x,j) => j < expanded[i] ? x : -1e6));
  const exponentials = masked.map(r => { const m = Math.max(...r); return r.map(x => Math.exp(x-m)); });
  const denominators = exponentials.map(r => r.reduce((a,b) => a+b,0));
  const alpha = exponentials.map((r,i) => r.map(x => x/denominators[i]));
  const colors = {background:'#fbf8f1',ink:'#252a2d',blue:'#356b91',orange:'#bd6935',quiet:'#d9d5cd'};
  const left = w < 460 ? 80 : 112;
  const cellW = (w-left-12)/4;
  const top = 83;
  const rowH = 42;
  const h = 270;
  const text = (x,y,s,fill=colors.ink,anchor='start',size=14) => `<text x="${x}" y="${y}" fill="${fill}" text-anchor="${anchor}" font-size="${size}">${s}</text>`;
  let parts = [`<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" role="img"><title>有效长度与掩蔽softmax</title><desc>固定手选评分，形状为2乘2乘4。${mode === 'row' ? '四行有效长度依次为1、3、2、4。' : '样本有效长度为2和3，展开后为2、2、3、3。'}每格上方为评分，下方为权重；橙色表示被掩蔽的位置，蓝色条长度表示权重。</desc><rect width="${w}" height="${h}" fill="${colors.background}"/><g font-family="sans-serif">`];
  parts.push(text(12,22,'X → α   (2, 2, 4)',colors.ink,'start',16));
  parts.push(text(12,44,mode === 'row' ? 'L = [[1, 3], [2, 4]]' : 'L = [2, 3]'));
  parts.push(text(w-12,22,'上 X / 下 α',colors.ink,'end'));
  parts.push(text(12,73,'样本·行'));
  for(let j=0;j<4;j++) parts.push(text(left+(j+0.5)*cellW,73,'k'+(j+1),colors.ink,'middle'));
  const cells = [];
  for(let i=0;i<4;i++) {
    const y = top+i*rowH;
    const b = Math.floor(i/2)+1;
    const q = i%2+1;
    parts.push(text(12,y+14,b+'·'+q));
    parts.push(text(12,y+33,'L='+expanded[i]));
    if(i===2) parts.push(`<line x1="12" y1="${y-4}" x2="${w-12}" y2="${y-4}" stroke="${colors.quiet}"/>`);
    for(let j=0;j<4;j++) {
      const x = left+j*cellW;
      const cx = x+cellW/2;
      const valid = j<expanded[i];
      const barW = (cellW-10)*alpha[i][j];
      if(valid) parts.push(`<rect x="${x+5}" y="${y+19}" width="${barW}" height="18" fill="${colors.blue}" fill-opacity="0.22"/>`);
      else parts.push(`<rect x="${x+5}" y="${y+1}" width="${cellW-10}" height="36" fill="${colors.orange}" fill-opacity="0.08"/>`);
      parts.push(text(cx,y+14,String(rows[i][j]),valid ? colors.ink : colors.orange,'middle'));
      if(!valid) parts.push(`<line x1="${cx-9}" y1="${y+9}" x2="${cx+9}" y2="${y+9}" stroke="${colors.orange}" stroke-width="1.5"/>`);
      parts.push(text(cx,y+33,valid ? alpha[i][j].toFixed(3) : '0',valid ? colors.ink : colors.orange,'middle'));
      cells.push({batch:b-1,query:q-1,key:j,x,y,width:cellW,height:rowH,valid,score:rows[i][j],maskedScore:masked[i][j],weight:alpha[i][j],barWidth:barW});
    }
  }
  parts.push('</g></svg>');
  return {svg:parts.join(''),facts:{example:'固定手选评分，非原文随机运行输出',state:mode,shape:[2,2,4],logits:X,validLens:lengths,flattenedRowOrder:[[0,0],[0,1],[1,0],[1,1]],expandedValidLens:expanded,maskedScores:masked,shiftedExponentials:exponentials,denominators,weights:alpha,rowSums:alpha.map(r=>r.reduce((a,b)=>a+b,0)),steps:['按样本与查询顺序展开四行','将键下标大于等于有效长度的评分替换为-1000000','逐行减最大值、取指数并归一化'],geometry:{width:w,height:h,left,top,rowHeight:rowH,cellWidth:cellW,cells}}};
}

function render({width,state,params}) {
  const w = Number.isFinite(width) ? Math.max(320, Math.min(760,width)) : 640;
  const supplied = params && params.d;
  const d = Number.isFinite(supplied) ? Math.max(1,Math.min(16,Math.round(supplied))) : 8;
  const key = typeof state === 'string' ? state : state && state.key;
  const mode = key === 'scaled' ? 'scaled' : 'raw';
  const root = Math.sqrt(d);
  const distribution = [];
  let probability = Math.pow(2,-d);
  for(let j=0;j<=d;j++) {
    if(j>0) probability *= (d-j+1)/j;
    const score = d-2*j;
    distribution.push({negativeProducts:j,raw:score,scaled:score/root,probability});
  }
  const total = distribution.reduce((s,p)=>s+p.probability,0);
  const rawMean = distribution.reduce((s,p)=>s+p.raw*p.probability,0);
  const scaledMean = distribution.reduce((s,p)=>s+p.scaled*p.probability,0);
  const rawVariance = distribution.reduce((s,p)=>s+(p.raw-rawMean)*(p.raw-rawMean)*p.probability,0);
  const scaledVariance = distribution.reduce((s,p)=>s+(p.scaled-scaledMean)*(p.scaled-scaledMean)*p.probability,0);
  const maxP = Math.max(...distribution.map(p=>p.probability));
  const colors = {background:'#fbf8f1',ink:'#252a2d',blue:'#356b91',orange:'#bd6935',quiet:'#c9c5bd'};
  const h = 268;
  const left = 44;
  const right = w-28;
  const limit = Math.max(4,d);
  const mapX = value => left+(value+limit)/(2*limit)*(right-left);
  const text = (x,y,s,fill=colors.ink,anchor='start',size=14) => `<text x="${x}" y="${y}" fill="${fill}" text-anchor="${anchor}" font-size="${size}">${s}</text>`;
  let parts = [`<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" role="img"><title>点积缩放的精确离散分布</title><desc>查询和键的每个分量独立地以相同概率取负一或正一，维度为${d}。蓝色为原始点积，橙色为缩放点积。每根竖线的高度表示概率，两个图使用相同坐标尺度。原始方差为${d}，缩放后方差为一。横向线段标出负一个至正一个标准差。</desc><rect width="${w}" height="${h}" fill="${colors.background}"/><g font-family="sans-serif">`];
  parts.push(text(12,21,'等概率 ±1；竖线高度为概率'));
  parts.push(text(w-12,21,'d = '+d,colors.ink,'end'));
  const plots = [];
  const specs = [{name:'raw',label:'qᵀk',baseline:94,titleY:43,color:colors.blue,sigma:root,variance:d},{name:'scaled',label:'qᵀk / √d',baseline:204,titleY:153,color:colors.orange,sigma:1,variance:1}];
  for(const spec of specs) {
    const opacity = mode === spec.name ? 1 : 0.48;
    parts.push(text(left,spec.titleY,spec.label,spec.color,'start',16));
    parts.push(text(right,spec.titleY,'Var = '+spec.variance,colors.ink,'end'));
    parts.push(`<line x1="${left}" y1="${spec.baseline}" x2="${right}" y2="${spec.baseline}" stroke="${colors.quiet}"/>`);
    parts.push(`<line x1="${left-4}" y1="${spec.baseline-44}" x2="${left-4}" y2="${spec.baseline}" stroke="${colors.quiet}"/>`);
    parts.push(text(left-8,spec.baseline-38,maxP.toFixed(2),colors.ink,'end'));
    parts.push(text(left-8,spec.baseline-3,'0',colors.ink,'end'));
    parts.push(`<line x1="${mapX(0)}" y1="${spec.baseline-44}" x2="${mapX(0)}" y2="${spec.baseline}" stroke="${colors.quiet}" stroke-dasharray="2 3"/>`);
    const marks = [];
    parts.push(`<g opacity="${opacity}">`);
    for(const point of distribution) {
      const value = point[spec.name];
      const x = mapX(value);
      const stemHeight = 44*point.probability/maxP;
      const y = spec.baseline-stemHeight;
      parts.push(`<line x1="${x}" y1="${spec.baseline}" x2="${x}" y2="${y}" stroke="${spec.color}" stroke-width="1.5"/><circle cx="${x}" cy="${y}" r="2" fill="${spec.color}"/>`);
      marks.push({value,probability:point.probability,x,y,stemHeight});
    }
    parts.push('</g>');
    for(const tick of [-limit,-limit/2,0,limit/2,limit]) {
      const x = mapX(tick);
      parts.push(`<line x1="${x}" y1="${spec.baseline}" x2="${x}" y2="${spec.baseline+4}" stroke="${colors.quiet}"/>`);
      parts.push(text(x,spec.baseline+19,String(tick),colors.ink,'middle'));
    }
    const spanY = spec.baseline+30;
    const x1 = mapX(-spec.sigma);
    const x2 = mapX(spec.sigma);
    parts.push(`<path d="M ${x1} ${spanY-3} V ${spanY+3} M ${x1} ${spanY} H ${x2} M ${x2} ${spanY-3} V ${spanY+3}" fill="none" stroke="${spec.color}" stroke-width="1.5"/>`);
    parts.push(text(mapX(0),spanY+16,'σ = '+(spec.sigma===1 ? '1' : spec.sigma.toFixed(2)),spec.color,'middle'));
    plots.push({name:spec.name,baseline:spec.baseline,color:spec.color,opacity,marks,standardDeviationSpan:{from:-spec.sigma,to:spec.sigma,x1,x2,y:spanY}});
  }
  parts.push('</g></svg>');
  return {svg:parts.join(''),facts:{state:mode,d,componentDistribution:[{value:-1,probability:0.5},{value:1,probability:0.5}],independence:'所有查询分量和键分量互相独立',productDistribution:[{value:-1,probability:0.5},{value:1,probability:0.5}],distribution,probabilitySum:total,rawMean,scaledMean,rawVariance,scaledVariance,theoreticalVariances:{raw:d,scaled:1},standardDeviations:{raw:root,scaled:1},steps:['以二项分布精确计算负乘积的个数j的概率','点积为d-2j','各支持点除以sqrt(d)，概率保持不变'],geometry:{width:w,height:h,xDomain:[-limit,limit],left,right,sharedProbabilityHeight:44,sharedMaximumProbability:maxP,plots}}};
}
